set-variable.value:
@{
      var claims = ((Jwt)context.Variables["validatedJwt"]).Claims;
      var hasRole = claims.ContainsKey("roles") && claims["roles"].Any(value => value == "{{required-app-role}}");
      var version = claims.GetValueOrDefault("ver", "");
      var actor = version == "2.0" ? claims.GetValueOrDefault("azp", "") : version == "1.0" ? claims.GetValueOrDefault("appid", "") : "";
      var scopes = claims.GetValueOrDefault("scp", "").Split(' ');
      var hasDesktopScope = scopes.Any(value => value == "{{claude-desktop-delegated-scope}}");
      return hasRole || ("{{claude-desktop-delegated-auth-enabled}}" == "true" && actor == "{{claude-desktop-client-id}}" && hasDesktopScope);
    }

@{
          try {
            var encoded = (string)context.Variables["inventoryConfiguration"];
            if (encoded.Length > 16384) { throw new Exception(); }
            var config = JObject.Parse(Encoding.UTF8.GetString(Convert.FromBase64String(encoded)));
            var accountToken = config["account_resource_id"];
            var pins = config["pins"] as JObject;
            if (accountToken == null || accountToken.Type != JTokenType.String || pins == null) { throw new Exception(); }
            var account = (string)accountToken;
            if (!Regex.IsMatch(account, @"\A/subscriptions/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/resourceGroups/[\p{L}\p{Nd}_().-]{0,89}[\p{L}\p{Nd}_()-]/providers/Microsoft\.CognitiveServices/accounts/[a-z0-9][a-z0-9_.-]{1,63}\z", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant)) { throw new Exception(); }
            foreach (var role in new [] { "opus", "sonnet", "haiku" }) {
              if (pins[role] == null || pins[role].Type != JTokenType.String || !Regex.IsMatch((string)pins[role], @"\A[A-Za-z0-9][A-Za-z0-9_.-]*\z")) { throw new Exception(); }
            }
            var path = string.Join("/", account.Split('/').Select(segment => Uri.EscapeDataString(segment))) + "/deployments";
            var state = new JObject();
            state["account"] = account;
            state["path"] = path;
            state["pins"] = pins;
            state["next"] = "https://management.azure.com" + path + "?api-version=2024-10-01";
            state["seen"] = new JArray();
            state["ids"] = new JArray();
            state["data"] = new JArray();
            state["count"] = 0;
            using (var hash = System.Security.Cryptography.SHA256.Create()) {
              state["accountKey"] = "claude-foundry:models:source:" + Convert.ToBase64String(hash.ComputeHash(Encoding.UTF8.GetBytes(account.ToLowerInvariant())));
              state["cacheKey"] = "claude-foundry:models:v1:" + Convert.ToBase64String(hash.ComputeHash(Encoding.UTF8.GetBytes(account.ToLowerInvariant() + "\n" + pins.ToString(Newtonsoft.Json.Formatting.None))));
            }
            return state.ToString(Newtonsoft.Json.Formatting.None);
          } catch { throw new Exception("Model inventory unavailable."); }
        }

@{
              try {
                var state = JObject.Parse((string)context.Variables["inventoryState"]);
                if ((string)state["next"] != "") { throw new Exception(); }
                var models = (JArray)state["data"];
                var pins = (JObject)state["pins"];
                var result = new JArray();
                var emitted = new HashSet<string>(StringComparer.Ordinal);
                foreach (var role in new [] { "opus", "sonnet", "haiku" }) {
                  var model = models.FirstOrDefault(row => (string)row["id"] == (string)pins[role]);
                  if (model != null && emitted.Add((string)model["id"])) { result.Add(model); }
                }
                foreach (var model in models.OrderBy(row => (string)row["id"], StringComparer.Ordinal)) {
                  if (emitted.Add((string)model["id"])) { result.Add(model); }
                }
                var body = new JObject(new JProperty("data", result)).ToString(Newtonsoft.Json.Formatting.None);
                if (DateTime.UtcNow.Subtract((DateTime)context.Variables["inventoryStarted"]).TotalSeconds >= 5) { throw new Exception(); }
                return body;
              } catch { throw new Exception("Model inventory unavailable."); }
            }
